class TextureReference {public static void main(String[] a)throws Exception{String[] names={"advanced_diamond_drill","advanced_iridium_drill","advanced_chainsaw","gravitool/wrench","advanced_nano_leggings","advanced_quantum_boots"};Path base=Path.of("src/main/resources/assets/ic2r_addons/textures/item");try(var s=Files.list(base)){s.forEach(System.out::println);}BufferedImage out=new BufferedImage(768,256,2);Graphics2D g=out.createGraphics();g.setColor(new Color(38,41,48));g.fillRect(0,0,768,256);String[] refs={"tool/electric/drill","tool/electric/diamond_drill","tool/electric/iridium_drill","tool/electric/chainsaw","tool/electric/electric_wrench","armor/nano_leggings"};for(int i=0;i<6;i++){var p=base.resolve(names[i]+".png");if(Files.exists(p))g.drawImage(ImageIO.read(p.toFile()),i*128,0,128,128,null);g.drawImage(ImageIO.read(Path.of("C:/GIT/IC2R/src/main/resources/assets/ic2/textures/item/"+refs[i]+".png").toFile()),i*128,128,128,128,null);}g.dispose();ImageIO.write(out,"png",Path.of("tools/textures/1.2.0-preview.png").toFile());}}
